public final class PriceRules {
  // Discount is expressed in basis points; the discount amount rounds down.
  static int discountedTotal(int units, int centsPerUnit, int discountBasisPoints) {
    int gross = units * centsPerUnit;
    return gross - gross * discountBasisPoints / 10000;
  }
}

