export interface Rate {
  baseCents: number;
  perItemCents: number;
  discountPercent: number;
}
export function quote(itemCount: number, rate: Rate): number {
  return Math.round((rate.baseCents + itemCount * rate.perItemCents) * (100 - rate.discountPercent) / 100);
}
